{
  "id": 23,
  "knowledge": "Hot Jupiter",
  "description": "A class of exoplanets that are physically similar to Jupiter but orbit very close to their stars.",
  "definition": "A planet that is classified as both a Gas Giant Planet and a Short-Period Planet."
}

{
  "id": 20,
  "knowledge": "Gas Giant Planet",
  "description": "A large planet composed primarily of gases like hydrogen and helium.",
  "definition": "A planet with a mass greater than 0.1 Jupiter masses."
}

{
  "id": 22,
  "knowledge": "Short-Period Planet",
  "description": "A planet that orbits its host star in a very short amount of time.",
  "definition": "A planet with an orbital period of less than 10 days."
}

{
  "id": 42,
  "knowledge": "Stellar Temperature Value",
  "description": "Illustrates the value for a star's effective surface temperature.",
  "definition": "Measured in Kelvin (K). Cool red dwarfs can be around 3,000 K, a Sun-like star is about 5,800 K, and very hot blue stars can exceed 30,000 K."
}

{
  "id": 44,
  "knowledge": "Stellar Radius Value",
  "description": "Illustrates the value for a star's radius.",
  "definition": "Measured in solar radii ($R_{\\odot}$), where 1 is the radius of our Sun. Values range from small neutron stars to giant stars like Betelgeuse, which would extend beyond the orbit of Mars if in our solar system."
}

{
  "id": 47,
  "knowledge": "Planet Mass Value",
  "description": "Illustrates the value for a planet's mass.",
  "definition": "Typically measured in Jupiter masses ($M_J$). Earth's mass is about 0.003 $M_J$. Known exoplanets range from less than Earth's mass to over 20 times the mass of Jupiter."
}

{
  "id": 45,
  "knowledge": "Orbital Period Value",
  "description": "Illustrates the value for the time a planet takes to complete one orbit around its star.",
  "definition": "Measured in days. 'Hot Jupiters' can have periods of only a few days, while planets in very distant orbits can have periods of many thousands of years."
}
